import groovy.json.JsonSlurper

plugins {
    id("com.android.library") version "9.4.1"
    `maven-publish`
}

// One version for every @pts/* package (ADR 0014): Changesets writes it to package.json.
val npmPackage = JsonSlurper().parse(file("package.json")) as Map<*, *>
group = "io.github.haaanju.pts"
version = npmPackage["version"] as String

android {
    namespace = "io.github.haaanju.pts"
    compileSdk = 37

    defaultConfig {
        minSdk = 23
    }

    // The Kotlin generated by plugin-compose.ts; run `npm run build` first
    sourceSets {
        getByName("main") {
            kotlin.directories += "dist"
        }
    }

    publishing {
        singleVariant("release") {
            withSourcesJar()
        }
    }
}

dependencies {
    // PtsColors uses Color and @Immutable; consumers get them through the library
    api(platform("androidx.compose:compose-bom:2026.09.00"))
    api("androidx.compose.ui:ui-graphics")
    api("androidx.compose.runtime:runtime")
}

publishing {
    publications {
        register<MavenPublication>("release") {
            artifactId = "pts-android"
            afterEvaluate { from(components["release"]) }
        }
    }
}
